public CompletableFuture<UserProfile> fetchUserProfile(String userId) {
    ExecutorService ioExecutor = Executors.newVirtualThreadPerTaskExecutor();

    return CompletableFuture
        .supplyAsync(() -> databaseClient.queryUser(userId), ioExecutor)
        .thenApplyAsync(user -> enrichWithPreferences(user), ioExecutor)
        .exceptionally(ex -> {
            logger.error("Failed to fetch user profile", ex);
            return UserProfile.defaultProfile();
        });
}
